"""Transcribes Federal Reserve Distributional Financial Accounts (DFA) series, as displayed on FRED
(retrieved 2026-11-22 via page extraction; FRED last updated 2026-09-18), into a CSV.
Series: WFRBST01122 (top 1%), WFRBSN09149 (90-99th), WFRBSN40176 (50-90th) shares of corporate
equities and mutual fund shares, percent of aggregate. Bottom 50% (WFRBSB50203) was only visible for
2025Q2-2026Q2 (0.6 each); for other quarters we impute bottom50 = 100 - (top1 + p90_99 + p50_90),
floored at 0.1, and flag it as imputed."""
import csv, os
top1 = """42.8 42.8 41.9 41.9 39.7 40.6 41.8 41.4 41.8 43.0 42.5 42.4 42.5 44.1 44.9 45.6 46.3 47.1 47.4 47.8 48.3 48.8 49.5 50.1 50.8 50.4 49.9 49.4 49.0 48.6 48.2 48.3 48.2 47.9 48.2 48.0 47.1 47.1 46.4 46.2 45.3 45.7 45.5 44.6 44.1 42.8 41.3 41.5 39.6 40.9 41.3 41.0 39.9 40.7 40.8 42.5 43.4 44.6 45.3 45.9 46.4 46.9 47.0 47.2 47.5 47.7 48.4 48.4 48.6 49.0 49.3 49.5 49.7 49.5 49.1 48.8 48.1 46.9 46.1 47.1 47.8 47.8 47.9 47.5 47.9 48.1 48.4 48.3 47.5 47.7 48.1 47.9 48.1 48.0 48.4 48.4 48.5 49.1 49.5 49.9 50.1 50.4 50.6 50.7 50.9 51.1 51.4 51.6 51.8 51.8 51.8 51.9 52.0 52.0 52.1 52.1 52.2 52.1 52.3 52.3 52.3 52.0 51.3 51.3 51.1 51.1 51.0 50.9 50.8 50.7 50.3 49.7 49.3 49.5 49.6 49.7 49.7 49.9 50.1 50.1 50.3 50.3 50.3 50.4 50.5 50.6 50.6 50.9"""
p9099 = """38.8 38.6 38.6 38.4 38.5 38.1 37.7 37.6 37.3 37.0 36.9 36.7 36.5 36.1 35.7 35.3 35.0 34.7 34.3 33.8 33.5 33.1 32.9 32.7 32.6 32.9 33.1 33.2 33.3 33.4 33.5 33.8 34.0 34.0 34.3 34.3 34.1 34.8 35.1 35.5 35.8 36.1 36.4 36.6 36.9 37.2 37.5 37.7 38.1 37.8 37.6 37.5 37.4 37.2 36.9 36.6 36.4 36.2 35.9 35.7 35.4 35.5 35.5 35.5 35.6 35.6 35.7 35.7 35.7 35.8 35.8 35.9 35.9 36.0 36.1 36.3 36.5 36.7 37.0 37.1 37.2 37.4 37.5 37.7 37.8 37.6 37.5 37.4 37.5 37.3 37.2 37.1 37.0 36.9 36.8 36.7 36.7 36.5 36.4 36.2 36.1 36.0 35.9 35.8 35.6 35.5 35.4 35.3 35.2 35.3 35.4 35.5 35.6 35.7 35.7 35.8 35.9 35.9 36.0 36.1 36.1 36.3 36.5 36.6 36.7 36.8 36.9 37.0 37.1 37.1 37.3 37.5 37.7 37.7 37.6 37.6 37.6 37.5 37.4 37.4 37.4 37.4 37.4 37.3 37.3 37.2 37.3 37.2"""
p5090 = """17.2 17.4 18.2 18.4 20.2 19.8 19.1 19.6 19.5 18.6 19.1 19.5 19.5 18.3 17.9 17.6 17.1 16.7 16.8 16.8 16.6 16.5 16.0 15.6 15.1 15.2 15.5 15.8 16.2 16.3 16.7 16.2 16.2 16.4 16.0 16.1 17.1 16.5 16.9 16.8 17.4 16.8 16.8 17.3 17.7 18.7 19.6 19.4 20.7 19.9 19.7 20.1 21.3 20.8 20.9 19.7 19.1 18.2 17.7 17.5 17.3 16.8 16.6 16.3 15.9 15.7 15.0 15.0 14.7 14.2 13.9 13.6 13.4 13.6 13.8 13.9 14.3 15.4 15.8 14.8 14.1 13.9 13.7 14.0 13.5 13.4 13.4 13.5 14.3 14.2 13.9 14.2 14.2 14.3 14.0 14.1 14.1 13.7 13.5 13.2 13.2 13.0 12.9 12.8 12.9 12.7 12.6 12.5 12.4 12.3 12.1 11.9 11.8 11.6 11.6 11.5 11.3 11.4 11.2 11.1 11.0 11.1 11.6 11.5 11.6 11.5 11.5 11.5 11.6 11.6 11.8 12.2 12.5 12.4 12.3 12.2 12.2 12.1 11.9 11.9 11.8 11.8 11.8 11.7 11.6 11.6 11.6 11.4"""
t, a, b = [list(map(float, s.split())) for s in (top1, p9099, p5090)]
assert len(t) == len(a) == len(b) == 148, (len(t), len(a), len(b))
here = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(here, '..', 'data', 'dfa_equity_shares.csv')
obs_b50 = {(2025, 2): 0.6, (2025, 3): 0.6, (2025, 4): 0.6, (2026, 1): 0.6, (2026, 2): 0.6}
with open(out, 'w', newline='') as f:
    w = csv.writer(f); w.writerow(['year', 'quarter', 'top1', 'p90_99', 'p50_90', 'bottom50', 'bottom50_imputed'])
    y, q = 1989, 3
    for i in range(148):
        if (y, q) in obs_b50: b50, imp = obs_b50[(y, q)], 0
        else: b50, imp = max(0.1, round(100 - t[i] - a[i] - b[i], 2)), 1
        w.writerow([y, q, t[i], a[i], b[i], b50, imp])
        q += 1
        if q == 5: q, y = 1, y + 1
print('wrote', out, 'last quarter', y, q - 1)
